action.code:
for (Node* neighbor : graph.get_neighbors(current_node)) {
    if (neighbor->visited) {
        continue;
    }

    double tentative_g = current_node->g + graph.get_edge_weight(current_node, neighbor);
    bool found_in_open = false;

    for (Node* open_node : open_list) {
        if (open_node == neighbor) {
            found_in_open = true;
            if (tentative_g < neighbor->g) {
                neighbor->g = tentative_g;
                neighbor->h = graph.heuristic(neighbor, end_node);
                neighbor->parent = current_node;
            }
            break;
        }
    }

    if (!found_in_open) {
        neighbor->g = tentative_g;
        neighbor->h = graph.heuristic(neighbor, end_node);
        neighbor->parent = current_node;
        open_list.push_back(neighbor);
    }
}

